import sys
from collections import defaultdict

def main():
    import sys
    import heapq

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    n, m = read_ints()
    k = read_ints()
    offers = [read_ints() for _ in range(m)]

    # Sort offers by day
    offers.sort()

    # Priority queue to store the days when each type of microtransaction will be on sale
    sale_days = [[] for _ in range(n + 1)]
    for d, t in offers:
        heapq.heappush(sale_days[t], d)

    current_day = 0
    burles = 0

    while True:
        # Check if we can buy all microtransactions today
        can_buy_all = True
        for i in range(1, n + 1):
            if k[i - 1] > 0:
                if sale_days[i] and sale_days[i][0] <= current_day:
                    burles += 1
                    heapq.heappop(sale_days[i])
                else:
                    burles += 2
                k[i - 1] -= 1
                if k[i - 1] < 0:
                    can_buy_all = False
                    break

        if can_buy_all:
            print(current_day + 1)
            return

        # Move to the next day
        current_day += 1
        burles += 1

if __name__ == "__main__":
    main()
